#include <stdio.h>
#include <stdlib.h>

#define MOD 1000000007LL

static long long mod_pow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = (r * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return r;
}

int main(void) {
    long long N, A;
    if (scanf("%lld %lld", &N, &A) != 2) return 0;

    /* 
       Let the permutation be decomposed into cycles.
       A cycle is "good" iff it contains at least one initially-on lamp.
       Then every lamp in a good cycle can be turned on eventually; a cycle
       with no initially-on lamp stays entirely unreachable.

       Therefore the player wins iff every cycle contains at least one of the
       first A positions, i.e. no cycle lies completely inside the last N-A
       positions.

       Count permutations of [1..N] with no cycle entirely contained in the
       set of size M = N-A.

       By inclusion-exclusion over subsets of the M "off" elements that form
       unions of whole cycles, the count is:
         ans = sum_{k=0..M} (-1)^k * C(M,k) * k! * (N-k)!
             = N! * sum_{k=0..M} (-1)^k / k!

       Since the problem asks for probability * N!, this is exactly the count.
    */

    long long M = N - A;

    long long maxN = N;
    long long *fact = (long long*)malloc((maxN + 1) * sizeof(long long));
    long long *invfact = (long long*)malloc((maxN + 1) * sizeof(long long));
    if (!fact || !invfact) return 0;

    fact[0] = 1;
    for (long long i = 1; i <= maxN; ++i) fact[i] = fact[i - 1] * i % MOD;

    invfact[maxN] = mod_pow(fact[maxN], MOD - 2);
    for (long long i = maxN; i > 0; --i) invfact[i - 1] = invfact[i] * i % MOD;

    long long sum = 0;
    for (long long k = 0; k <= M; ++k) {
        if (k & 1) {
            sum -= invfact[k];
            if (sum < 0) sum += MOD;
        } else {
            sum += invfact[k];
            if (sum >= MOD) sum -= MOD;
        }
    }

    long long ans = fact[N] * sum % MOD;
    printf("%lld\n", ans);

    free(fact);
    free(invfact);
    return 0;
}

