const int MOD = 1e9 + 7;

long long power(long long a, long long b, long long mod) {
    long long res = 1; a %= mod;
    while (b > 0) { if (b & 1) res = res * a % mod; a = a * a % mod; b >>= 1; }
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N, A;
    cin >> N >> A;

    int M = N - A; // number of OFF lamps

    // Precompute factorials and inverse factorials
    vector<long long> fact(N + 1), inv_fact(N + 1);
    fact[0] = 1;
    for (int i = 1; i <= N; i++) fact[i] = fact[i-1] * i % MOD;
    inv_fact[N] = power(fact[N], MOD - 2, MOD);
    for (int i = N - 1; i >= 0; i--) inv_fact[i] = inv_fact[i+1] * (i+1) % MOD;

    long long ans = 0;
    for (int k = 0; k <= M; k++) {
        long long term = inv_fact[k] % MOD * inv_fact[M - k] % MOD * fact[N - k] % MOD;
        if (k % 2 == 0) ans = (ans + term) % MOD;
        else ans = (ans - term + MOD) % MOD;
    }
    ans = ans % MOD * fact[M] % MOD; // multiply by M! for C(M,k) = M!/(k!(M-k)!)

    cout << ans << endl;
    return 0;
}

