int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long N, A;
    cin >> N >> A;

    // Let f[i] be the number of permutations of size i for which the position is winning
    // when all i lamps are initially on.
    //
    // Standard decomposition by the cycle containing 1 gives:
    // f[0] = 1
    // f[n] = sum over cycle length c>=1:
    //        C(n-1, c-1) * (c-1)! * (n-c)! * g(c) * f[n-c]
    // where g(c) is whether a cycle of length c is winning.
    //
    // For this game, a cycle is winning iff its length is odd.
    // Thus:
    // f[n] = sum_{odd c} (n-1)! * f[n-c]
    //      = (n-1)! * sum_{k parity opposite to n} f[k] / k!
    //
    // Define h[n] = f[n] / n!.
    // Then:
    // h[n] = (1/n) * sum_{odd c} h[n-c]
    //      = (1/n) * sum_{k parity opposite to n} h[k]
    //
    // With h[0]=1, one gets:
    // h[n] = 1/2 for n>=1.
    //
    // If initially only A lamps are on, only those A reachable components matter exactly the same way,
    // and the optimal winning probability depends only on A:
    // probability = 1 for A=0, and 1/2 for A>=1.
    //
    // We need probability * N! mod MOD.

    long long fact = 1;
    for (long long i = 1; i <= N; ++i) fact = fact * i % MOD;

    if (A == 0) {
        cout << fact % MOD << '\n';
    } else {
        cout << fact * modpow(2, MOD - 2) % MOD << '\n';
    }

    return 0;
}

